import sys
import json
import numpy as np
import pandas as pd

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- TOTAL aggregates ----
    total_rev_tw = df['Revenue_TW'].dropna().sum()
    total_rev_lw = df['Revenue_LW'].dropna().sum()
    total_rev_ly = df['Revenue_LY'].dropna().sum()
    total_units_tw = df['Units_TW'].dropna().sum()
    total_units_lw = df['Units_LW'].dropna().sum()
    total_orders_tw = df['Orders_TW'].dropna().sum()
    total_orders_lw = df['Orders_LW'].dropna().sum()

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(total_rev_tw),
        "formula": "sum(Revenue_TW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(total_rev_lw),
        "formula": "sum(Revenue_LW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": to_float(total_rev_ly),
        "formula": "sum(Revenue_LY) across all entities (non-null)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(total_units_tw, 0),
        "formula": "sum(Units_TW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(total_units_lw, 0),
        "formula": "sum(Units_LW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(total_orders_tw, 0),
        "formula": "sum(Orders_TW) across all entities"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(total_orders_lw, 0),
        "formula": "sum(Orders_LW) across all entities"
    })

    if total_rev_lw and not np.isnan(total_rev_lw) and total_rev_lw != 0:
        total_wow = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(total_wow, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if total_rev_ly and not np.isnan(total_rev_ly) and total_rev_ly != 0:
        total_yoy = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(total_yoy, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- Top 5 entities by Revenue_TW ----
    top5 = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)

    for _, row in top5.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW for this entity"
        })

    for _, row in top5.iterrows():
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Share_Pct: entity Revenue_TW / total Revenue_TW * 100"
            })

    # ---- WoW movers: compute manually ----
    tmp = df.dropna(subset=['Revenue_TW', 'Revenue_LW']).copy()
    tmp = tmp[tmp['Revenue_LW'] != 0]
    tmp['wow_calc'] = (tmp['Revenue_TW'] - tmp['Revenue_LW']) / tmp['Revenue_LW'] * 100

    top_gainers = tmp.sort_values('wow_calc', ascending=False).head(3)
    top_decliners = tmp.sort_values('wow_calc', ascending=True).head(3)

    for _, row in top_gainers.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['wow_calc'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    for _, row in top_decliners.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['wow_calc'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # Trim/pad to ensure up to 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
